local PkgImage = require("pkg_image")
local B,W=15,0
local pages={"余量","趋势","资源"}
local function header(g,s) g:clear(W); PkgImage.draw(g, "brand_logo", 24, 18); g:text(334,32,"LongCat-2.0",{color=B}); g:line(24,78,456,78,{color=B}); for i,v in ipairs(pages) do local x=24+(i-1)*144; g:text(x+34,102,v,{color=B}); if s.page==i then g:line(x+18,132,x+102,132,{color=B}); g:line(x+18,135,x+102,135,{color=B}) end end end
local function meter(g,x,y,w,used,total) g:line(x,y+15,x+w,y+15,{color=B}); g:rect(x,y+10,math.floor(w*used/total),10,{fill=true,color=B}) end
local function overview(g,s) header(g,s); PkgImage.draw(g, "feature_scene", 120, 150); PkgImage.draw(g, "icon_token", 24, 326); g:text(88,330,"剩余",{color=B}); g:text(88,374,"18.42M",{color=B}); g:text(342,374,"61.4%",{color=B}); g:line(24,424,456,424,{color=B}); g:text(24,458,"主资源包",{color=B}); meter(g,24,496,432,11.58,30); g:text(24,530,"已用 11.58M",{color=B}); g:text(326,530,"总量 30M",{color=B}); g:line(24,578,456,578,{color=B}); PkgImage.draw(g, "icon_wallet", 24, 610); g:text(88,612,"按量余额",{color=B}); g:text(344,612,"¥286.40",{color=B}); PkgImage.draw(g, "icon_cat", 24, 682); g:text(88,684,"今日消耗",{color=B}); g:text(344,684,"1.58M",{color=B}) end
local function trend(g,s) header(g,s); g:text(24,158,"近 7 日用量",{color=B}); local values={1.82,2.14,1.67,2.86,3.42,2.31,1.58}; local labels={"20","21","22","23","24","25","26"}; local total=0; for i,v in ipairs(values) do total=total+v; local x=32+(i-1)*61; local h=math.floor(v/3.5*300); g:rect(x,520-h,34,h,{fill=true,color=B}); g:text(x+4,538,labels[i],{color=B}) end; g:line(24,520,456,520,{color=B}); g:text(24,592,"7 日合计",{color=B}); g:text(24,634,string.format("%.2fM tokens",total),{color=B}); g:text(300,634,"均值 2.26M",{color=B}); g:line(24,676,456,676,{color=B}); g:text(24,710,"今日较昨日下降 31.6%",{color=B}) end
local function resources(g,s) header(g,s); g:text(24,158,"资源状态",{color=B}); PkgImage.draw(g, "icon_key", 24, 198); g:text(88,200,"主资源包",{color=B}); g:text(88,236,"30M Tokens · 有效期至 09-19",{color=B}); meter(g,24,276,432,11.58,30); g:line(24,332,456,332,{color=B}); PkgImage.draw(g, "icon_alert", 24, 358); g:text(88,362,"用量告警",{color=B}); local rows={{"剩余低于 20%","已开启"},{"日消耗超过 5M","已开启"},{"错误率超过 3%","已开启"},{"到期前 3 天","已开启"}}; for i,v in ipairs(rows) do local y=424+(i-1)*62; g:text(42,y,v[1],{color=B}); g:text(356,y,v[2],{color=B}); g:line(42,y+38,456,y+38,{color=B}); if i==1 then g:rect(24,y-4,5,40,{fill=true,color=B}) end end; g:line(24,690,456,690,{color=B}); g:text(44,722,"运行正常 · 预计可用约 8 天",{color=B}) end
function on_load(ctx) if not ctx.state.longcat then ctx.state.longcat={page=1} end; ctx:set_tick(0) end
function on_draw(ctx,g) require("pkg_image").bind(ctx); local s=ctx.state.longcat; if s.page==1 then overview(g,s) elseif s.page==2 then trend(g,s) else resources(g,s) end end
function on_input(ctx,ev) if not (ev.type == "pointer" and ev.phase == "up") then return false end; local s=ctx.state.longcat; if ev.gesture=="swipe_left" then s.page=s.page%3+1 elseif ev.gesture=="swipe_right" then s.page=(s.page+1)%3+1 elseif ev.gesture=="tap" and ev.y>=88 and ev.y<=140 then s.page=math.max(1,math.min(3,math.floor((ev.x-24)/144)+1)) else return false end; ctx:invalidate(); return true end
